package com.amplayer.portable;
import android.app.*;import android.content.*;import android.os.*;import android.net.Uri;import android.provider.MediaStore;import android.view.*;import android.webkit.*;import org.json.*;import java.io.*;import java.nio.*;import java.util.*;
public class Shared2110Instrumentation extends Instrumentation {
 private JSONObject settings;private final List<Uri> created=new ArrayList<>();
 private void report(String key,String value){Bundle b=new Bundle();b.putString(key,value);sendStatus(0,b);}
 private WebView web(View v){if(v instanceof WebView)return (WebView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){WebView found=web(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
 private JSONObject track(String name)throws Exception{ContentValues values=new ContentValues();values.put(MediaStore.Audio.Media.DISPLAY_NAME,"AMPlayer-queue-"+name+"-"+System.currentTimeMillis()+".wav");values.put(MediaStore.Audio.Media.MIME_TYPE,"audio/wav");values.put(MediaStore.Audio.Media.RELATIVE_PATH,"Music/AMPlayerTest");Uri uri=getTargetContext().getContentResolver().insert(MediaStore.Audio.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new Exception("Fixture failed");created.add(uri);int bytes=16000*40;ByteBuffer wave=ByteBuffer.allocate(44+bytes).order(ByteOrder.LITTLE_ENDIAN);wave.put("RIFF".getBytes()).putInt(36+bytes).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(8000).putInt(16000).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(bytes);try(OutputStream out=getTargetContext().getContentResolver().openOutputStream(uri)){wave.putShort(44,(short)name.hashCode());out.write(wave.array());}return new JSONObject().put("name",name).put("type","local").put("path",uri.toString());}
 private void save()throws Exception{Store.save(getTargetContext(),settings.toString());}
 private JSONObject status()throws Exception{return new JSONObject(PlaybackService.status());}
 private String path(JSONObject s){return s.optJSONObject("item")==null?"":s.optJSONObject("item").optString("path");}
 private JSONObject await(String expected)throws Exception{JSONObject s=new JSONObject();for(int n=0;n<100;n++){Thread.sleep(200);s=status();if(path(s).equals(expected)&&s.optBoolean("playing"))return s;}throw new Exception("Expected "+expected+" but got "+s);}
 private void startTrack(JSONObject item,String context)throws Exception{JSONObject value=new JSONObject(item.toString()).put("playbackContext",context);settings.put("playbackContext",context);save();runOnMainSync(()->getTargetContext().startForegroundService(new Intent(getTargetContext(),PlaybackService.class).setAction("item").putExtra("item",value.toString())));await(item.getString("path"));}
 private void command(String name){runOnMainSync(()->getTargetContext().startService(new Intent(getTargetContext(),PlaybackService.class).setAction(name)));}
 private void endTrack(){runOnMainSync(()->PlaybackService.seek(39700));}
 private void repeats(String expected)throws Exception{endTrack();boolean wrapped=false;for(int n=0;n<100;n++){Thread.sleep(150);JSONObject s=status();if(!path(s).equals(expected))throw new Exception("Single repeat changed track: "+s);if(s.optBoolean("playing")&&s.optLong("position")<15000){wrapped=true;break;}}if(!wrapped)throw new Exception("Single repeat did not restart");}
 private android.webkit.WebView actualWeb;
 private String js(String code)throws Exception{java.util.concurrent.CountDownLatch latch=new java.util.concurrent.CountDownLatch(1);java.util.concurrent.atomic.AtomicReference<String> value=new java.util.concurrent.atomic.AtomicReference<>();runOnMainSync(()->actualWeb.evaluateJavascript(code,r->{value.set(r);latch.countDown();}));if(!latch.await(15,java.util.concurrent.TimeUnit.SECONDS))throw new Exception("JS timeout");return value.get();}
 private void waitJS(String expression)throws Exception{for(int n=0;n<100;n++){if("true".equals(js(expression)))return;Thread.sleep(150);}throw new Exception("UI condition failed: "+expression+" state="+js("JSON.stringify(state)"));}
 private String stringJS(String expression)throws Exception{return String.valueOf(new JSONTokener(js(expression)).nextValue());}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 @Override public void onStart(){Bundle result=new Bundle();JSONObject original=Store.load(getTargetContext());try{
  JSONObject a=track("ShareA"),b=track("ShareB"),c=track("ExistingC");String cp=c.getString("path");
  settings=new JSONObject(original.toString()).put("stations",new JSONArray()).put("volume",0).put("autoUpdate",false).put("localFiles",new JSONArray().put(c)).put("favorites",new JSONArray().put(c)).put("playlists",new JSONArray()).put("sharedPlaylistId","").put("lastPlayed",c).put("playbackContext","local");save();
  Activity activity=startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->actualWeb=web(activity.getWindow().getDecorView()));waitJS("typeof state!=='undefined'&&!!state");js("state.selectedPlaylistId='';showPage('local');playItem(state.localFiles[0]);true");await(cp);
  ArrayList<Uri> batch=new ArrayList<>();batch.add(Uri.parse(a.getString("path")));batch.add(Uri.parse(b.getString("path")));IncomingMusic.accept(getTargetContext(),new Intent(Intent.ACTION_SEND_MULTIPLE).setType("audio/wav").putParcelableArrayListExtra(Intent.EXTRA_STREAM,batch).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));
  waitJS("state.localFiles.length===3&&state.playlists.length===1");String ap=stringJS("state.localFiles[0].path"),bp=stringJS("state.localFiles[1].path");waitJS("state.localFiles[0].originalName.includes('ShareA')&&state.localFiles[1].originalName.includes('ShareB')&&state.playlists[0].paths[0]===state.localFiles[0].path&&state.playlists[0].paths[1]===state.localFiles[1].path");if(!path(status()).equals(cp)||!status().optBoolean("playing"))throw new Exception("SEND interrupted playback");report("batchShare","PASS SEND_MULTIPLE prepends A/B in order, creates shared playlist, C keeps playing");
  command("pause");Thread.sleep(400);IncomingMusic.accept(getTargetContext(),new Intent(Intent.ACTION_SEND).setType("audio/wav").putExtra(Intent.EXTRA_STREAM,Uri.parse(b.getString("path"))).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));waitJS("state.localFiles[0].path==="+JSONObject.quote(bp));if(status().optBoolean("playing"))throw new Exception("SEND unexpectedly autoplayed while paused");waitJS("state.localFiles.length===3&&state.playlists[0].paths.length===2");report("repeatShare","PASS repeat share moves B to first without duplicate file/list entry or autoplay");
  js("S.renamePlaylist(state,state.sharedPlaylistId,'收件匣');persist(true);true");IncomingMusic.accept(getTargetContext(),new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse(a.getString("path")),"audio/wav").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));await(ap);waitJS("state.playlists.length===1&&state.playlists[0].name==='收件匣'&&state.playbackContext==='playlist'&&state.activePlaylistId===state.sharedPlaylistId");report("viewOpen","PASS ACTION_VIEW plays A within shared playlist; renamed shared playlist reused");
  js("api.command('stop');stopped=true;observed={};S.deletePlaylist(state,state.sharedPlaylistId);persist(true);true");Thread.sleep(400);IncomingMusic.accept(getTargetContext(),new Intent(Intent.ACTION_SEND).setType("audio/wav").putExtra(Intent.EXTRA_STREAM,Uri.parse(b.getString("path"))).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));waitJS("state.playlists.length===1&&state.playlists[0].name==='來自分享'&&state.playlists[0].paths.length===1");if(status().optBoolean("playing"))throw new Exception("Recreated share playlist autoplayed");report("recreate","PASS deleting shared playlist preserves music and next share recreates it without autoplay");
  for(String path:new String[]{ap,bp}){File f=new File(new File(getTargetContext().getFilesDir(),"Music"),Uri.parse(path).getLastPathSegment());f.delete();new File(f.getPath()+".json").delete();}
  result.putString("result","PASS");finish(Activity.RESULT_OK,result);
 }catch(Throwable e){result.putString("failure",e.toString());finish(Activity.RESULT_CANCELED,result);}finally{getTargetContext().stopService(new Intent(getTargetContext(),PlaybackService.class));for(Uri uri:created)getTargetContext().getContentResolver().delete(uri,null,null);try{Store.save(getTargetContext(),original.toString());}catch(Exception ignored){}}}
}
